import os
import re

from taf.rfrl.common_resources.oam_kpi.report_oam_kpi import report_oam_kpi, ReportOamKpi
from taf.rfrl.utilities.robot.general import set_robot_test_variable
from taf.sbts.oam.coam.admin import admin
from taf.ul.oam_kpi_calculations import oam_kpi_calculations
from taf.ul.oam_kpi_calculations.exceptions import OamKpiCalculationsException
from taf.sw.reporting_portal import reporting_portal
from taf.sbts.oam.coam.admin.exceptions import AliasInUse
from taf.rfrl.uuf4all.resources.python.uuf_rfrl_common import get_competence_area, add_report_to_dictionary, \
    get_admin_connection
from taf.rfrl.uuf4all.resources.python.uuf_rfrl_utilities import robot_logger, robot_var, run_kw, robot_kw
from taf.rfrl.uuf4all.resources.python.uuf_rfrl_variables import KPI_PER_TEST_CASE

kpi_calc = oam_kpi_calculations()
kpi_calc.log_warning = False
admin = admin()
ute_reporting_portal = reporting_portal()


def setup_admin_connection_for_kpi_ims():
    try:
        admin.setup_admin(bts_host=robot_var("BTS_HOST_IP"), update_interval=500, alias="KPI_IMS")
    except AliasInUse:
        admin.teardown("KPI_IMS")
        admin.setup_admin(bts_host=robot_var("BTS_HOST_IP"), update_interval=500, alias="KPI_IMS")



def report_kpi_results():
    report_summary_to_reporting_portal()
    kpi_calc.clear_results()


def report_success_ratio():
    kpi_name = robot_var("KPI_NAME")
    kpi_results = robot_var("KPI_RESULTS")
    if not any(kpi_id in kpi_name for kpi_id in ["kpi16", "kpi17"]) and not kpi_name == "kpi5":
        kpi_name = kpi_name[:-1]
    ReportOamKpi().report_oam_kpi_success_rate(kpi_name=kpi_name,
                                               passed_iterations=robot_var("LOOP_RESULTS").count("passed"),
                                               executed_iterations=len(robot_var("LOOP_RESULTS")))
    kpi_results.append({"id": ReportOamKpi()._get_success_rate_kpi_id(kpi_name),
                        "value": str(robot_var("LOOP_RESULTS").count("passed")),
                        "target": str(len(robot_var("LOOP_RESULTS"))),
                        "source": "OAMKPI"})


def get_uuf_kpi(reset=False, update=False):
    try:
        if reset:
            return str(kpi_calc.get_all_deltas("kpi1a")[-1])
        if update:
            return str(kpi_calc.get_all_deltas(get_kpi_name_for_update())[-1])
    except Exception as exception:
        robot_logger("Given KPI not found in deltas", "info", False)
        robot_logger(exception, "info", False)
        return "0"


def collect_infomodel_logs_for_oam_kpi(test_phase, file_suffix=None, admin_alias=None):
    test_case_name = robot_var("TEST_NAME")
    ims_file_name = "OAM_KPI{}.ims2".format("_" + str(file_suffix) if file_suffix else "")
    ims_path = "/".join([robot_var("LOG_PATH"), test_case_name, test_phase])
    ims_file_path = "/".join([robot_var("LOG_PATH"), robot_var("TEST_NAME"), test_phase, ims_file_name])
    admin.collect_infomodel_log_from_current_session(target_file_name=ims_file_path, timeout=500,
                                                     connection=get_admin_connection() if not admin_alias
                                                     else admin_alias)
    return ims_path


def get_kpi_name_for_update():
    uboot_downgrade = True if robot_var("FIRMWARE_BEFORE_UPDATE") != robot_var("FIRMWARE_AFTER_UPDATE") else False
    inter_release_update = robot_var("INTER_RELEASE_UPDATE")
    if inter_release_update and not uboot_downgrade:
        return "kpi2a"
    elif inter_release_update and uboot_downgrade:
        return "kpi2b"
    elif not inter_release_update and not uboot_downgrade:
        return "kpi2c"
    return "kpi2d"


def calculate_proper_oam_kpi(test_phase, file_suffix=None, update_scenario=False):
    if robot_var("DISABLE_KPI"):
        try:
            if update_scenario:
                admin.teardown("KPI_UPDATE")
            else:
                admin.teardown("KPI_IMS")
        except Exception as e:
            robot_logger(e, "info", False)
    else:
        try:
            kpi_calc.save_search_end_timestamp()
            test_case_name = robot_var("TEST_NAME")
            kpi_names = KPI_PER_TEST_CASE.get(test_case_name.lower())
            for test_name, kpi in KPI_PER_TEST_CASE.items():
                if test_name in test_case_name.lower():
                    kpi_names = kpi
            if not kpi_names:
                return
            if update_scenario:
                file_suffix = "update"
                kpi_names = [get_kpi_name_for_update()]
                set_robot_test_variable("UPDATE_KPI", kpi_names[0])
                collect_infomodel_logs_for_oam_kpi(test_phase, file_suffix)
                ims_path = collect_infomodel_logs_for_oam_kpi(test_phase, file_suffix="update_1",
                                                              admin_alias="KPI_UPDATE")
                admin.teardown("KPI_UPDATE")
            else:
                ims_path = collect_infomodel_logs_for_oam_kpi(test_phase, file_suffix, admin_alias="KPI_IMS")
                admin.teardown("KPI_IMS")
            ims_files = sorted(["/".join([ims_path, ims_file]) for ims_file in os.listdir(ims_path)
                                if re.match(r"OAM_KPI{}.*\.ims2".format("_" + file_suffix if file_suffix else ""),
                                            ims_file)], reverse=True)
            ims_dir_path = os.path.dirname(ims_path)
            try:
                kpi_calc.calculate_kpis(kpi_names=kpi_names, ims_file_path=ims_files)
            except OamKpiCalculationsException as kpi_exception:
                robot_logger(kpi_exception, "warn")
            set_robot_test_variable("KPI_NAME", kpi_names[0])
            calculated_kpis = kpi_calc.get_results()
            kpi_calc.save_results_to_file(os.path.join(ims_dir_path, 'kpi_results.json'))
            report_oam_kpi(oam_kpi_results=kpi_calc.get_latest_results(), log_warn=False,
                           oam_kpi_targets=robot_var("OAM_KPI_TARGETS"))
            kpi_results = ReportOamKpi().prepare_kpi_results(oam_kpi_results=calculated_kpis, log_warn=False,
                                                             oam_kpi_targets=robot_var("OAM_KPI_TARGETS"))
            set_robot_test_variable('KPI_RESULTS', kpi_results)
        except Exception as exception:
            robot_logger("Error Occured During KPI calculation {}."
                         "Kpi for current Loop will not be added to result".format(exception),
                         "warn", False)


@robot_kw
def clear_kpi_results():
    kpi_calc.clear_results()


def log_kpi_results():
    if not robot_var("DISABLE_KPI"):
        if robot_var("KPI_RESULTS") is not None:
            robot_logger("Calculated KPI RESULTS", "info", False)
            robot_logger(robot_var("KPI_RESULTS"), "info", False)
        else:
            robot_logger("No KPI calculated for current test", "info", False)
        clear_kpi_results()


def report_summary_to_reporting_portal():
    if not robot_var("DISABLE_KPI"):
        loop_results = robot_var("LOOP_RESULTS")
        status = "failed" if "failed" in loop_results or not loop_results else "passed"
        count = len(loop_results) if loop_results else 1
        cm_execution_id = os.environ.get("CM_EXECUTION_ID")
        set_report_tags(robot_var("KPI_QC_DOMAIN"), robot_var("KPI_QC_PROJECT"), robot_var("TEST_ID"))
        try:
            kpi_res = robot_var("KPI_RESULTS") if robot_var("KPI_RESULTS") is not None else ""
            ute_reporting_portal.add_to_test_data(data=str({"tc_execution_id": robot_var("TC_EXEC_ID"), "test_loops": str(count)}))
            if cm_execution_id is None:
                link_to_rp = run_kw('taf.sw.reporting_portal.report to rp',
                                    name=robot_var("TEST_NAME"),
                                    result=status,
                                    ca=get_competence_area(robot_var('TEST_TAGS')),
                                    testline=robot_var('HOSTNAME'),
                                    build=robot_var('RESERVED_BUILD') if robot_var("REPORT_SW") is None
                                    else robot_var("REPORT_SW"),
                                    qc_domain=robot_var("KPI_QC_DOMAIN") if robot_var("KPI_QC_DOMAIN") is not None
                                    else "",
                                    qc_project=robot_var("KPI_QC_PROJECT") if robot_var(
                                            "KPI_QC_PROJECT") is not None else "",
                                    qc_id=str(robot_var("TEST_ID")) if robot_var("TEST_ID") is not None else "",
                                    label=robot_var('LABEL'),
                                    tool='WebEM',
                                    kpi_results=kpi_res,
                                    links={},
                                    tc_execution_id=robot_var("TC_EXEC_ID"),
                                    test_loops=str(count)
                                    )
                robot_logger("Link to report : {}".format(link_to_rp), "info")
                add_report_to_dictionary(status, link_to_rp, summary_result=True)
        finally:
            clear_kpi_results()


def set_report_tags(qc_domain=None, qc_project=None, qc_id=None):
    if None not in [qc_id, qc_domain, qc_project]:
        run_kw("Set Tags", "QCD_{}".format(qc_domain), "QCP_{}".format(qc_project), "QC_{}".format(qc_id))
